import { platform, api, isPages } from './platform-client.js';
import { statuses, poStatuses } from './platform-core.js';
import { $,esc,money,date,icon,badge,toast,modal,closeModal,empty,formError } from './ui-kit.js';
import { genderNames } from './member-store.js';
import { privacyPolicy, memberRef } from './privacy.js';
const policyHtml=()=>`<dl class="privacy-list">${privacyPolicy.map(([t,d])=>`<dt>${esc(t)}</dt><dd>${esc(d)}</dd>`).join('')}</dl>`;
import { lineConfig, lineStartUrl, initLiff } from './line-login.js';
let line={enabled:false,demo:false,liffId:''};
let data,member=null,profile=null,orders=[],cart={},favorites=[],category='',concern='',query='',sort='recommended',checkout=null,requestKey=null,busy=false;
const scope=new URL('.',import.meta.url).pathname,params=new URL(location.href).searchParams;
// QRコードのURL（仕様書 2.2.2：entry?shop_id=S001）と従来の ?salon= の両方を受け付ける。
let salonId=params.get('shop_id')||params.get('salon')||localStorage.getItem('ss-salon:'+scope)||'lumiere';
const concernOrder=['ダメージヘア対策','エイジングケア','白髪対策','ボリュームアップ','頭皮ケア','カラーケア','パーマケア'];
const concerns=()=>[...new Set(data.products.flatMap(p=>p.concerns||[]))].sort((a,b)=>(concernOrder.indexOf(a)+99)%99-(concernOrder.indexOf(b)+99)%99);
const genderOptions=v=>Object.entries(genderNames).map(([k,n])=>`<option value="${k}" ${String(v??'')===k?'selected':''}>${n}</option>`).join('');
// クローズドサイト（仕様書 2.2.6）：商品閲覧・カート・購入は会員ログイン後のみ。
function requireMember(){if(member)return true;showAuth('login');toast('会員限定ストアです。ログインまたは会員登録をお願いします。');return false;}
const route=()=>location.hash.slice(1)||'home';
// 会員の担当サロンが受付停止中のときは null を返し、カート・注文を止める（別のサロンに差し替えない）。
const salon=()=>data.salons.find(s=>s.id===salonId)||(profile?null:data.salons[0]);
const mySalonName=()=>salon()?.name||(profile?.salonName?`${profile.salonName}（受付停止中）`:'');
// QRの担当スタッフ指定は、そのサロンに在籍するスタッフのときだけ使う。
const qrStaff=()=>{const id=params.get('staff')||'';return data.salons.find(s=>s.id===salonId)?.staff.some(s=>s.id===id)?id:'';};
const lineErrors={cancelled:'LINEログインがキャンセルされました。',expired:'ログインの有効期限が切れました。もう一度お試しください。',conflict:'このLINEアカウントは別の会員に連携済みです。',failed:'LINEログインに失敗しました。'};
// カートとお気に入りは会員ごとにサーバーへ保存する（別の端末でも続きから買い物できる）。
// 保存は順番に送り、読み込みは送信待ちが終わってから行う（追加直後の自動更新で戻らないように）。
let pendingSave=Promise.resolve();
const persist=(route,body)=>{pendingSave=pendingSave.then(()=>platform(route,'PUT',body)).catch(error=>toast(error.message));return pendingSave;};
async function loadCart(){checkout=null;requestKey=null;if(!member){cart={};favorites=[];return;}await pendingSave;const [c,f]=await Promise.all([platform('/cart'),platform('/favorites')]);cart=Object.fromEntries(Object.entries(c.items||{}).filter(([id])=>data.products.some(p=>p.id===id)));favorites=(f.ids||[]).filter(id=>data.products.some(p=>p.id===id));}
function saveCart(){checkout=null;requestKey=null;const count=$('#cart-count');if(count)count.textContent=Object.values(cart).reduce((a,b)=>a+b,0);if(member)persist('/cart',{items:{...cart}});}
function lines(){return Object.entries(cart).map(([id,quantity])=>({...data.products.find(p=>p.id===id),quantity})).filter(p=>p.id);}
function payload(){return lines().map(({id,quantity,price})=>({id,quantity,price}));}
function summary(q){return `<div class="total-list"><div><span>商品小計（税込）</span><span>${money(q.subtotal)}</span></div><div><span>送料（税込）</span><span>${q.shipping?money(q.shipping):'無料'}</span></div><div class="grand"><span>合計</span><strong>${money(q.total)}</strong></div></div>`;}
function totals(){const subtotal=lines().reduce((s,p)=>s+p.price*p.quantity,0),shipping=subtotal===0||subtotal>=11000?0:660;return {subtotal,shipping,total:subtotal+shipping};}
function header(){const count=Object.values(cart).reduce((a,b)=>a+b,0);return `<div class="demo-ribbon"><span>EXPERIENCE DEMO</span>架空の商品で購入体験をお試しください。実際の決済・発送は行われません。</div><header class="store-header"><a class="store-logo" href="./">SALON STATION<small>YOUR SALON, YOUR EVERYDAY</small></a><button class="salon-select" data-choose-salon>${icon('store')}<span>MY SALON<br><b>${esc(mySalonName()||'サロンを選択')}</b></span>${icon('chevron')}</button><div class="store-header-actions"><button data-page="account" aria-label="マイページ・ログイン">${icon('user')}<span class="action-label">${member?'マイページ':'ログイン'}</span></button>${member?`<button data-page="orders" aria-label="購入履歴">${icon('clock')}<span class="action-label">購入履歴</span></button><button data-cart aria-label="カートを開く">${icon('bag')}<span class="action-label">カート</span><b class="cart-count" id="cart-count">${count}</b></button>`:`<button data-auth="register" aria-label="新規会員登録">${icon('leaf')}<span class="action-label">会員登録</span></button>`}</div></header><nav class="store-nav" aria-label="メインメニュー"><button class="${route()==='home'?'active':''}" data-page="home">ホーム</button>${member?`<button class="${route()==='catalog'?'active':''}" data-page="catalog">すべての商品</button><button data-favorites>お気に入り</button>`:'<button data-auth="register">新規会員登録</button>'}<button data-choose-salon>マイサロン</button><button data-guide>ご利用ガイド</button></nav>`;}
function gate(){return `<section class="store-content" id="member-gate"><div class="store-section-head"><div><div class="eyebrow">MEMBERS ONLY</div><h2>Members Only<span>会員限定ストア</span></h2></div></div><div class="account-layout"><div class="account-panel"><h2>サロンのお客様専用ストアです</h2><p>サロン専売品を取り扱うため、商品と価格はログイン後にご覧いただけます。</p><button class="btn primary" data-auth="login">ログインする ${icon('arrow')}</button><p class="subtle-note">体験用：ログイン画面の「架空のデモ会員を作成して体験する」からすぐにお試しいただけます。</p></div><div class="account-panel"><h2>はじめての方</h2><p>サロン店頭のQRコードを読み取るか、マイサロンを選んで会員登録してください。登録と同時にサロン・担当スタッフと紐付きます。</p><button class="btn outline" data-auth="register">新規会員登録 ${icon('arrow')}</button><p class="subtle-note">現在のマイサロン：${esc(salon()?.name||'未選択')}</p></div></div></section>`;}
function footer(){return `<footer class="store-footer"><div class="footer-top"><div class="store-logo">SALON STATION<small>YOUR SALON, YOUR EVERYDAY</small></div><div class="footer-links"><button data-guide>ご利用ガイド</button><button data-privacy>お客様情報の取り扱い</button><button data-choose-salon>サロンを選ぶ</button><button data-page="account">会員登録・マイページ</button><a href="./admin.html" target="_blank" rel="noopener">管理画面へ ${icon('external')}</a><a href="./order.html" target="_blank" rel="noopener">加盟店の発注画面 ${icon('external')}</a></div></div><div class="footer-bottom"><span>© 2026 SALON STATION. All products and salons are fictional.</span><span>${isPages?'公開デモの注文は同じブラウザ内だけで連動します。':'ローカル版：このサーバーに接続した画面間で注文が連動します。'}</span></div></footer>`;}
function hero(){return `<section class="store-hero"><div class="store-hero-copy"><div class="eyebrow">A LITTLE CARE. A BEAUTIFUL EVERYDAY.</div><h1>サロンで出会った、<br>わたしの定番を。</h1><p>担当スタイリストが選ぶ、あなたのためのヘアケア。<br>いつものサロンから、ご自宅へお届けします。</p><button class="btn primary" data-page="catalog">わたしのヘアケアを見つける ${icon('arrow')}</button></div><div class="store-hero-visual"><img class="hero-main-img" src="./assets/shampoo.png" alt="SENAのヘアケアコレクション"><div class="hero-small-card"><strong>SENA PROFESSIONAL</strong>DAILY HAIR CARE COLLECTION</div><div class="hero-caption"><span>SELECTED BY YOUR SALON</span><span>01 / EVERYDAY CARE</span></div></div></section><div class="store-benefits"><div>${icon('leaf')}<span><b>サロンが選ぶヘアケア</b><small>担当スタッフのおすすめを日常に</small></span></div><div>${icon('truck')}<span><b>ディーラーから直送</b><small>ご自宅までていねいにお届け</small></span></div><div>${icon('bag')}<span><b>11,000円以上で送料無料</b><small>通常送料660円・すべて税込</small></span></div></div>`;}
function catalog(){return `<section class="store-content" id="catalog"><div class="store-section-head"><div><div class="eyebrow">CURATED FOR YOU</div><h2>${category==='favorites'?'Favorites':'Our Selection'}<span>${category==='favorites'?'お気に入り':'あなたのためのヘアケア'}</span></h2></div><p id="result-count"></p></div><div class="product-tools"><div class="pill-rows"><div class="category-pills">${[['','すべて'],['シャンプー','シャンプー'],['トリートメント','トリートメント'],['ヘアオイル','ヘアオイル']].map(([id,name])=>`<button data-category="${id}" class="${category===id?'active':''}">${name}</button>`).join('')}</div><div class="category-pills concern-pills"><span class="pills-label">お悩みから探す</span>${[['','指定なし'],...concerns().map(c=>[c,c])].map(([id,name])=>`<button data-concern="${esc(id)}" class="${concern===id?'active':''}">${esc(name)}</button>`).join('')}</div></div><div class="product-search"><select id="sort" aria-label="商品の表示順"><option value="recommended">おすすめ順</option><option value="price-asc">価格の安い順</option><option value="price-desc">価格の高い順</option></select><input id="product-query" type="search" aria-label="商品を検索" placeholder="商品名・ブランドから探す" value="${esc(query)}">${icon('search')}</div></div><div class="product-grid" id="product-grid"></div><div class="salon-message"><div class="salon-monogram">${esc(salon()?.name.slice(0,1)||'S')}</div><div><div class="eyebrow">FROM YOUR SALON / ${esc(salon()?.area||'')}</div><h3>${esc(salon()?.description||'あなたの日常に、サロンのケアを。')}</h3><p>${esc(salon()?.name||'')} のおすすめをご自宅でも。お気に入りのケアを、何度でも。</p></div><button class="text-link" data-choose-salon>サロン情報を見る ${icon('arrow')}</button></div></section>`;}
function renderProducts(){if(!$('#product-grid'))return;let rows=data.products.filter(p=>(!category||category==='favorites'?category!=='favorites'||favorites.includes(p.id):p.category===category)&&(!concern||(p.concerns||[]).includes(concern))&&`${p.name} ${p.brand} ${p.sku} ${p.description||''}`.toLowerCase().includes(query.toLowerCase()));if(sort!=='recommended')rows.sort((a,b)=>sort==='price-asc'?a.price-b.price:b.price-a.price);$('#result-count').textContent=`${rows.length} items`;$('#sort').value=sort;$('#product-grid').innerHTML=rows.length?rows.map(p=>`<article class="product-card"><div class="photo"><button data-product="${p.id}" aria-label="${esc(p.name)}の詳細"><img src="./assets/${p.image}" alt="${esc(p.name)}" loading="lazy"></button>${p.tag?`<span class="product-tag">${esc(p.tag)}</span>`:''}<button class="favorite-btn ${favorites.includes(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="${esc(p.name)}をお気に入り${favorites.includes(p.id)?'から削除':'に追加'}" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button>${!p.stock?'<span class="soldout-layer">SOLD OUT</span>':''}</div><p class="brand-label">${esc(p.brand)}</p><button class="product-name" data-product="${p.id}">${esc(p.name)}</button><p class="size">${esc(p.size)}</p><div class="product-bottom"><div class="price">${money(p.price)}<small>税込</small></div><button class="add-cart" data-add="${p.id}" ${p.stock?'':'disabled'}>${p.stock?'カートに追加':'入荷待ち'} ${icon('bag')}</button></div></article>`).join(''):empty('商品が見つかりません',category==='favorites'?'商品のハートを押すと、ここに保存されます。':'検索条件を変えてお試しください。');}
function accountPage(){if(!member)return `<section class="store-page"><h1>My Account</h1><p class="subtle-note">サロンとつながって、いつものヘアケアをもっと身近に。</p><div class="account-layout"><div class="account-panel"><h2>会員の方</h2><p>ログインして購入履歴や配送状況をご確認ください。</p><button class="btn primary" data-auth="login">ログインする ${icon('arrow')}</button></div><div class="account-panel"><h2>はじめての方</h2><p>マイサロンを登録すると、お買い物をお楽しみいただけます。</p><button class="btn outline" data-auth="register">新規会員登録 ${icon('arrow')}</button><p class="subtle-note">デモ用の架空情報で登録を体験できます。</p></div></div></section>`;
  return `<section class="store-page"><h1>My Account</h1><p class="subtle-note">${esc(member.name)} さん、こんにちは。</p><div class="account-layout"><div class="account-panel"><div class="eyebrow">YOUR MEMBERSHIP</div><h2>${esc(member.name)}${member.kana?`<small class="kana">（${esc(member.kana)}）</small>`:''}</h2><p>${esc(member.email)}${member.phone?` / ${esc(member.phone)}`:''}</p><p>マイサロン：${esc(mySalonName()||'未設定')}</p><p>担当スタッフ：${esc(data.salons.find(s=>s.id===profile?.salonId)?.staff.find(s=>s.id===profile?.staffId)?.name||'指名なし')}</p><p>会員番号：${esc(memberRef(member.id))}</p><p>会員登録日：${date(member.createdAt)}</p><p>LINE連携：${member.lineId?'連携済み':line.enabled&&!line.demo?`<button class="text-link" data-line-link>LINEアカウントを連携する ${icon('arrow')}</button>`:'未連携'}</p><div class="form-actions"><button class="btn outline small" data-logout>ログアウト</button><button class="btn primary small" data-page="orders">購入履歴を見る</button></div></div><div class="account-panel"><h2>登録情報の変更</h2><form id="profile-form" class="stack"><label>お名前<input name="name" value="${esc(member.name)}" maxlength="80" required></label><div class="form-grid"><label>フリガナ<input name="kana" value="${esc(member.kana||'')}" maxlength="50"></label><label>電話番号<input name="phone" value="${esc(member.phone||'')}" maxlength="15" inputmode="tel"></label><label>性別<select name="gender">${genderOptions(member.gender)}</select></label><label>生年月日<input name="birthday" type="date" value="${esc(member.birthday||'')}"></label></div><label>マイサロン<input value="${esc(mySalonName()||'未設定')}" readonly aria-readonly="true"><input type="hidden" name="salonId" value="${esc(profile?.salonId||salonId)}"></label><label>担当スタッフ<select name="staffId" id="profile-staff">${staffOptions(salonId,profile?.staffId)}</select></label><p class="subtle-note">担当サロンの変更は、ご利用のサロンまたは運営本部にご依頼ください。担当スタッフはここで変更できます。</p><div id="form-error" class="error" role="alert"></div><button class="btn primary" type="submit">変更を保存する</button></form></div></div></section>`;}
function staffOptions(id,selected=''){return '<option value="">指名なし</option>'+(data.salons.find(s=>s.id===id)?.staff||[]).map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('');}
function orderPage(){return `<section class="store-page"><h1>My Orders</h1><p class="subtle-note">ご注文とお届けの状況をご確認いただけます。</p>${!member?empty('ログインして購入履歴を確認','ご本人の注文だけが表示されます。','<button class="btn primary" data-auth="login">ログインする</button>'):orders.length?orders.map(o=>`<article class="order-card"><div class="order-card-head"><div><b>${o.id}</b><small>　${date(o.createdAt)}</small></div>${badge(o.status,statuses[o.status])}</div><p class="subtle-note">${esc(o.salonName)} / ${esc(o.staffName)}</p>${o.items.map(p=>`<div class="order-line"><img src="./assets/${p.image}" alt="${esc(p.name)}"><div class="line-copy"><strong>${esc(p.name)}</strong><br><small>${esc(p.size)} × ${p.quantity}</small></div><span>${money(p.price*p.quantity)}</span></div>`).join('')}<div class="order-card-foot"><div>ご注文合計<strong>${money(o.total)}</strong></div><button class="btn outline small" data-order="${o.id}">配送状況・詳細 ${icon('chevron')}</button></div></article>`).join(''):empty('購入履歴はまだありません','サロンおすすめの商品を探してみましょう。','<button class="btn primary" data-page="catalog">商品を見る</button>')}</section>`;}
function render(){const current=route();$('#app').innerHTML=header()+`<main>${current==='account'?accountPage():current==='orders'?orderPage():member?(current==='home'?hero():'')+catalog():hero()+gate()}</main>`+footer();renderProducts();}
async function refresh(){const [next,auth]=await Promise.all([platform('/bootstrap'),api('/auth/me')]);data=next;member=auth.member;profile=member?await platform('/profile'):null;if(profile)salonId=profile.salonId;else if(!data.salons.some(s=>s.id===salonId))salonId=data.salons[0]?.id||'';orders=member?await platform('/orders'):[];await loadCart();}
async function navigate(page){location.hash=page;if(route()===page){if(page==='orders'&&member)orders=await platform('/orders');render();}scrollTo({top:0,behavior:'smooth'});}
function add(id){if(!requireMember())return;if(!salon())throw Error('現在ご利用いただけるサロンがありません。');const p=data.products.find(p=>p.id===id);if(!p)return;if((cart[id]||0)>=Math.min(p.stock,99))throw Error('在庫数を超えて追加できません。');cart[id]=(cart[id]||0)+1;saveCart();toast('カートに追加しました。');}
function showCart(){if(!requireMember())return;if(!salon())return modal('ショッピングバッグ',empty('現在休業中です','サロンの受付再開までお待ちください。'));const items=lines();modal('ショッピングバッグ',items.length?`<p class="subtle-note">${esc(salon().name)} でのお買い物</p>${items.map(p=>`<div class="cart-line"><img src="./assets/${p.image}" alt="${esc(p.name)}"><div class="cart-line-copy"><h3>${esc(p.name)}</h3><p>${esc(p.size)} / ${money(p.price)}</p><div class="qty-control"><button data-qty="${p.id}" data-delta="-1" aria-label="${esc(p.name)}を1点減らす">−</button><span>${p.quantity}</span><button data-qty="${p.id}" data-delta="1" aria-label="${esc(p.name)}を1点増やす" ${p.quantity>=p.stock?'disabled':''}>＋</button></div><button class="remove-item" data-remove="${p.id}">削除</button>${p.quantity>p.stock?'<p class="error">在庫不足です。数量を減らしてください。</p>':''}</div><strong>${money(p.quantity*p.price)}</strong></div>`).join('')}${summary(totals())}<p class="subtle-note">11,000円以上で送料無料。分割出荷でも追加送料はかかりません。</p><div class="form-actions"><button class="btn outline" data-close>お買い物を続ける</button><button class="btn primary" data-checkout>お届け先へ進む ${icon('arrow')}</button></div>`:empty('バッグは空です','お気に入りのヘアケアを見つけてみましょう。','<button class="btn primary" data-close>お買い物を続ける</button>'));}
function showDetail(id){if(!requireMember())return;const p=data.products.find(p=>p.id===id);if(!p)return;modal('Product Details',`<div class="detail-product"><img src="./assets/${p.image}" alt="${esc(p.name)}"><div><div class="eyebrow">${esc(p.brand)}</div><h3>${esc(p.name)}</h3><p class="subtle-note">${esc(p.size)} / ${esc(p.sku)}</p>${(p.concerns||[]).length?`<p class="concern-tags">${p.concerns.map(c=>`<span>${esc(c)}</span>`).join('')}</p>`:''}<p class="description">${esc(p.description)}</p><p>${money(p.price)} <small>税込</small></p><p class="subtle-note">${p.stock?'在庫あり / ディーラー直送':'現在入荷待ちです'}</p><div class="form-actions"><button class="btn primary full" data-add="${p.id}" ${p.stock?'':'disabled'}>カートに追加 ${icon('bag')}</button></div><button class="text-link" data-cart>バッグを見る ${icon('arrow')}</button></div></div>`,true);}
function showSalon(){modal('マイサロンを選ぶ',`<p class="subtle-note">${profile?'担当サロンの変更は、ご利用のサロンまたは運営本部にご依頼ください。':'サロンからの紹介リンクで、あなたの担当サロンに登録できます。'}</p><div class="stack">${data.salons.map(s=>`<button class="salon-choice ${s.id===salonId?'selected':''}" data-select-salon="${s.id}"><span class="avatar">${esc(s.name.slice(0,1))}</span><div><b>${esc(s.name)}</b><small>${esc(s.area)}<br>${esc(s.description)}</small></div>${icon(s.id===salonId?'check':'chevron')}</button>`).join('')}</div>`);}
function showAuth(mode='login'){if(mode==='register'&&!salon())return toast('現在、新規登録を受け付けていません。');modal(mode==='login'?'おかえりなさい':'サロンとつながる会員登録',`<div class="login-tabs"><button class="${mode==='login'?'active':''}" data-auth="login">ログイン</button><button class="${mode==='register'?'active':''}" data-auth="register">新規会員登録</button></div><form id="member-form" data-mode="${mode}" class="stack">${mode==='register'?`<label>お名前<input name="name" required maxlength="80" placeholder="デモ 花子" autocomplete="off"></label><label>マイサロン<select name="salonId" id="register-salon">${data.salons.map(s=>`<option value="${s.id}" ${s.id===salonId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>担当スタッフ<select name="staffId" id="register-staff">${staffOptions(salonId,qrStaff())}</select></label><div class="form-grid"><label>フリガナ（任意）<input name="kana" maxlength="50" placeholder="デモ ハナコ" autocomplete="off"></label><label>電話番号（任意）<input name="phone" maxlength="15" placeholder="090-0000-0000" inputmode="tel" autocomplete="off"></label><label>性別（任意）<select name="gender">${genderOptions('')}</select></label><label>生年月日（任意）<input name="birthday" type="date" max="${new Date().toISOString().slice(0,10)}"></label></div>`:''}<label>デモ用メールアドレス<input name="email" type="email" required placeholder="member@example.test" autocomplete="username"></label><label>デモ用パスワード<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="12文字以上"></label><details class="privacy-box"${mode==='register'?' open':''}><summary>お客様情報の取り扱い</summary>${policyHtml()}</details>${mode==='register'?'<label class="check-label consent"><input type="checkbox" name="agreePrivacy" required>お客様情報の取り扱いに同意します</label>':''}<div id="form-error" class="error" role="alert"></div><button type="submit" class="btn primary full">${mode==='login'?'ログインする':'同意して会員登録する'}</button></form><div class="notice">架空情報のみでお試しください。メールは @example.test 専用です。${isPages?'公開版の認証はブラウザ内の体験用です。':''}</div>${line.enabled?`<div class="or-divider"><span>または</span></div><button class="btn line full" type="button" data-line-login>LINEで${mode==='login'?'ログイン':'登録'}${line.demo?'（デモ）':''}</button><p class="subtle-note">${line.demo?'公開版はLINEと通信せず、架空のLINE会員を作成して流れを体験します。':'LINEアカウントで登録・ログインできます。QR経由の場合はサロンに自動で紐付きます。'}</p>`:''}<div class="form-actions"><button class="btn soft full" data-demo-member>架空のデモ会員を作成して体験する</button></div><p class="subtle-note">LINEでの登録や、架空のデモ会員の作成でも、上の「お客様情報の取り扱い」に同意したものとして登録します。</p>`);}
function showCheckout(){if(!salon())return showCart();if(!member){showAuth('login');toast('購入には会員登録・ログインが必要です。');return;}if(!lines().length)return showCart();modal('お届け先の確認',`<div class="flow-steps"><span>バッグ</span><i></i><b>お届け先</b><i></i><span>注文確認</span></div><div class="notice">テスト注文用のお届け先です。実際の個人情報は入力しないでください。</div><form id="checkout-form" class="stack"><div class="form-grid"><label>お名前<input name="name" value="${esc(checkout?.customer.name||profile?.address?.name||member.name)}" required maxlength="80"></label><label>郵便番号<input name="postal" value="${esc(checkout?.customer.postal||profile?.address?.postal||'0000000')}" required pattern="[0-9]{3}-?[0-9]{4}" maxlength="8"></label><label class="span-2">住所<input name="address" value="${esc(checkout?.customer.address||profile?.address?.address||'デモ県サンプル市 1-2-3（架空の住所）')}" required maxlength="250"></label></div><div class="review-salon"><b>販売店：${esc(salon().name)}</b>${esc(salon().owner)}<br>商品は提携ディーラーから直送します。</div><p class="subtle-note">お支払い：テスト決済（カード情報の入力・請求はありません）</p><div id="form-error" class="error" role="alert"></div><div class="form-actions"><button type="button" class="btn outline" data-cart>バッグへ戻る</button><button type="submit" class="btn primary">注文内容を確認 ${icon('arrow')}</button></div></form>`);}
function showReview(){const {quote:q,customer:c}=checkout;modal('ご注文内容の確認',`<div class="flow-steps"><span>バッグ</span><i></i><span>お届け先</span><i></i><b>注文確認</b></div><div class="review-salon"><b>${esc(salon().name)}</b>販売事業者：${esc(salon().owner)}</div><dl class="detail-list"><dt>お届け先</dt><dd>${esc(c.name)} 様<br>〒${esc(c.postal)}<br>${esc(c.address)}</dd><dt>お支払い</dt><dd>テスト決済</dd><dt>お届け目安</dt><dd>通常1〜4営業日（デモ設定）</dd></dl>${q.items.map(p=>`<div class="order-line"><div class="line-copy"><strong>${esc(p.name)}</strong><br><small>${esc(p.size)} × ${p.quantity}</small></div><span>${money(p.price*p.quantity)}</span></div>`).join('')}${summary(q)}<p class="notice">注文確定に合わせて、仕入先別のテスト発注が自動作成されます。実際の決済・配送は行われません。</p><div id="form-error" class="error" role="alert"></div><div class="form-actions"><button class="btn outline" data-checkout>入力内容を修正</button><button class="btn primary" data-place-order>テスト注文を確定する</button></div>`);}
async function orderDetail(id){orders=await platform('/orders');const o=orders.find(o=>o.id===id);if(!o)return;modal('ご注文・配送の詳細',`<div class="between"><strong>${o.id}</strong>${badge(o.status,statuses[o.status])}</div><dl class="detail-list"><dt>販売店</dt><dd>${esc(o.salonName)}<br>${esc(o.seller)}</dd><dt>担当スタッフ</dt><dd>${esc(o.staffName)}</dd><dt>お届け先</dt><dd>${esc(o.customer.name)} 様<br>${esc(o.customer.address)}</dd><dt>お支払い</dt><dd>${esc(o.payment)} / ${money(o.total)}</dd></dl><h3>お届け状況</h3>${o.shipments.map(s=>`<div class="shipment"><div class="between"><b>${esc(s.dealerName)}</b>${badge(s.status,poStatuses[s.status])}</div><p>${s.items.map(p=>`${esc(p.name)} × ${p.quantity}`).join('<br>')}</p>${s.tracking?`<p>配送：${esc(s.carrier)}<br>追跡番号：<strong>${esc(s.tracking)}</strong></p>`:'<p class="subtle-note">出荷後に追跡番号をお知らせします。</p>'}</div>`).join('')}<ul class="timeline">${o.timeline.map(t=>`<li>${esc(t.label)}<time>${date(t.at,true)}</time></li>`).join('')}</ul>${o.returnReason?`<p class="return-reason">返品理由：${esc(o.returnReason)}</p>`:''}<div class="form-actions">${['ordered','processing'].includes(o.status)?`<button class="btn danger" data-confirm-cancel="${o.id}">注文をキャンセル</button>`:''}${['shipped','delivered'].includes(o.status)?`<button class="btn outline" data-return="${o.id}">返品を申請</button>`:''}<button class="btn primary" data-close>閉じる</button></div>`,true);}
async function afterAuth(){await refresh();if(!profile){await platform('/profile','PATCH',{salonId,staffId:''});await refresh();}render();closeModal();toast('ログインしました。お買い物をお楽しみください。');if(lines().length)showCart();else navigate('catalog');}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{
  if(b.dataset.page){await navigate(b.dataset.page);return;}
  if(b.hasAttribute('data-favorites')){if(!requireMember())return;category='favorites';await navigate('catalog');}
  if(b.dataset.category!==undefined){category=b.dataset.category;render();}
  if(b.dataset.concern!==undefined){concern=b.dataset.concern;render();}
  if(b.dataset.add)add(b.dataset.add);
  if(b.hasAttribute('data-cart')){data=await platform('/bootstrap');showCart();}
  if(b.dataset.product)showDetail(b.dataset.product);
  if(b.dataset.favorite){const id=b.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(p=>p!==id):[...favorites,id];persist('/favorites',{ids:[...favorites]});renderProducts();}
  if(b.hasAttribute('data-choose-salon'))showSalon();
  if(b.dataset.selectSalon){const next=b.dataset.selectSalon;if(profile){closeModal();if(next!==profile.salonId)toast('担当サロンの変更は、ご利用のサロンまたは運営本部にご依頼ください。');}else{salonId=next;localStorage.setItem('ss-salon:'+scope,salonId);checkout=null;closeModal();render();toast('マイサロンを選びました。');}}
  if(b.dataset.auth)showAuth(b.dataset.auth);
  if(b.hasAttribute('data-line-login')){b.disabled=true;if(line.demo){const result=await api('/auth/line/demo',{method:'POST',body:JSON.stringify({salon:salon()?.name||'',agreePrivacy:true})});member=result.member;await platform('/profile','PATCH',{salonId,staffId:qrStaff()});await afterAuth();}else location.href=lineStartUrl({salonId,staffId:qrStaff()});}
  if(b.hasAttribute('data-line-link'))location.href=lineStartUrl({salonId});
  if(b.hasAttribute('data-logout')){await api('/auth/logout',{method:'POST',body:'{}'});member=null;profile=null;orders=[];cart={};favorites=[];checkout=null;render();toast('ログアウトしました。');}
  if(b.hasAttribute('data-demo-member')){if(!salon())throw Error('現在、新規登録を受け付けていません。');b.disabled=true;const result=await api('/auth/register',{method:'POST',body:JSON.stringify({name:'デモ 花子',salon:salon().name,email:`member-${crypto.randomUUID().slice(0,8)}@example.test`,password:'Demo-Member-2026',agreePrivacy:true})});member=result.member;await platform('/profile','PATCH',{salonId,staffId:salon().staff[0]?.id||''});await afterAuth();}
  if(b.dataset.qty){const id=b.dataset.qty,p=data.products.find(p=>p.id===id),q=cart[id]+Number(b.dataset.delta);if(q<=0)delete cart[id];else if(q<=Math.min(99,p.stock)||Number(b.dataset.delta)<0)cart[id]=q;saveCart();showCart();}
  if(b.dataset.remove){delete cart[b.dataset.remove];saveCart();showCart();}
  if(b.hasAttribute('data-checkout'))showCheckout();
  if(b.hasAttribute('data-place-order')){if(busy)return;busy=true;b.disabled=true;try{requestKey??=crypto.randomUUID();const o=await platform('/orders','POST',{salonId,items:checkout.quote.items.map(({id,price,quantity})=>({id,price,quantity})),customer:checkout.customer,requestKey});cart={};checkout=null;requestKey=null;await refresh();render();modal('ご注文ありがとうございます',`<div class="success-copy"><div class="success-mark">${icon('check')}</div><h3>ご注文を受け付けました</h3><p>ご注文番号：<strong>${o.id}</strong></p><p>合計 ${money(o.total)} / ${esc(o.salonName)}</p><p>ディーラーへ自動発注しました。<br>配送状況は購入履歴からご確認いただけます。</p></div><div class="form-actions"><button class="btn outline" data-close>お買い物を続ける</button><button class="btn primary" data-order="${o.id}">配送状況を確認</button></div>`);}finally{busy=false;b.disabled=false;}}
  if(b.dataset.order)await orderDetail(b.dataset.order);
  if(b.dataset.confirmCancel)modal('注文をキャンセルしますか？',`<p class="description">出荷前の注文を取り消し、テスト返金と在庫の戻しを行います。</p><div class="form-actions"><button class="btn outline" data-order="${b.dataset.confirmCancel}">戻る</button><button class="btn danger" data-cancel="${b.dataset.confirmCancel}">キャンセルを確定</button></div>`);
  if(b.dataset.cancel){await platform('/orders/'+b.dataset.cancel+'/cancel','POST',{});await refresh();render();await orderDetail(b.dataset.cancel);toast('キャンセル・テスト返金が完了しました。');}
  if(b.dataset.return)modal('返品の申請',`<p class="subtle-note">注文全体の返品を受け付けます。管理側の検品完了後にテスト返金されます。</p><form id="return-form" data-order-id="${b.dataset.return}" class="stack"><label>返品理由<textarea name="reason" required maxlength="300" placeholder="デモ：注文する商品を間違えた"></textarea></label><div id="form-error" class="error" role="alert"></div><button class="btn primary" type="submit">返品を申請する</button></form>`);
  if(b.hasAttribute('data-privacy'))modal('お客様情報の取り扱い',`<p class="subtle-note">${member?`あなたの会員番号：<strong>${esc(memberRef(member.id))}</strong>。担当サロンの変更やお問い合わせのときにお伝えください。`:'会員登録の前にご確認ください。'}</p>${policyHtml()}`);
  if(b.hasAttribute('data-guide'))modal('ご利用ガイド',`<div class="stack"><h3>サロンのケアを、ご自宅へ。</h3><p>マイサロンを選び、会員登録後に商品を注文できます。注文は仕入先のディーラーへ自動で連携されます。</p><p>通常送料は注文1件につき660円。商品合計11,000円以上で無料です。複数ディーラーからの分割出荷でも追加送料はありません。</p><p>出荷前は購入履歴からキャンセルできます。全商品の出荷後は注文全体の返品を申請できます。</p><div class="notice">すべて架空の商品・店舗・注文の体験デモです。決済・メール・外部ディーラーへの送信・配送はシミュレーションです。${isPages?'会員・注文はこのブラウザに保存され、他の利用者とは共有されません。':'ローカルサーバーのデータで両画面が連動します。'} 実際の個人情報は入力しないでください。</div></div>`);
}catch(error){formError(error);b.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='product-query'){query=e.target.value;renderProducts();}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;renderProducts();}if(e.target.id==='register-salon')$('#register-staff').innerHTML=staffOptions(e.target.value);});
document.addEventListener('submit',async e=>{const form=e.target;if(!['member-form','checkout-form','profile-form','return-form'].includes(form.id))return;e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;const fields=Object.fromEntries(new FormData(form));try{
  if(form.id==='member-form'){if(form.dataset.mode==='register'){const s=data.salons.find(s=>s.id===fields.salonId);const result=await api('/auth/register',{method:'POST',body:JSON.stringify({...fields,salon:s.name,agreePrivacy:fields.agreePrivacy==='on'})});member=result.member;salonId=s.id;await platform('/profile','PATCH',{salonId,staffId:fields.staffId});}else await api('/auth/login',{method:'POST',body:JSON.stringify(fields)});await afterAuth();}
  if(form.id==='checkout-form'){const q=await platform('/quote','POST',{salonId,items:payload()});checkout={customer:fields,quote:q};requestKey=null;showReview();}
  if(form.id==='profile-form'){const salonName=data.salons.find(s=>s.id===fields.salonId)?.name||profile?.salonName||'未設定';await api('/auth/profile',{method:'PATCH',body:JSON.stringify({name:fields.name,salon:salonName,kana:fields.kana,phone:fields.phone,gender:fields.gender,birthday:fields.birthday})});await platform('/profile','PATCH',{salonId:fields.salonId,staffId:fields.staffId});await refresh();render();toast('登録情報を保存しました。');}
  if(form.id==='return-form'){await platform('/orders/'+form.dataset.orderId+'/return','POST',fields);await refresh();render();await orderDetail(form.dataset.orderId);toast('返品申請を受け付けました。');}
}catch(error){formError(error);}finally{b.disabled=false;}});
addEventListener('hashchange',()=>navigate(route()).catch(formError));
let checking=false;async function sync(){if(checking||busy||$('#modal').open||!data)return;checking=true;try{const previous=data.revision,oldMember=member?.id;const auth=await api('/auth/me');const next=await platform('/bootstrap');if(next.revision!==previous||auth.member?.id!==oldMember){await refresh();render();}}catch(error){toast(error.message);}finally{checking=false;}}
addEventListener('focus',sync);addEventListener('storage',sync);setInterval(()=>{if(!document.hidden)sync();},15000);
try{
  line=await lineConfig();
  await refresh();
  // LINEアプリ内（LIFF）で開かれた場合は、LIFFのIDトークンでログインする。
  if(!member&&line.liffId&&await initLiff(line.liffId))await refresh();
  // LINEログイン直後など、会員はいるがサロン未設定なら QR の店舗・担当スタッフで紐付ける（仕様書 2.2.7 ①）。
  if(member&&!profile){try{await platform('/profile','PATCH',{salonId,staffId:qrStaff()});await refresh();}catch(error){toast(error.message);}}
  const lineResult=params.get('line');
  if(lineResult)history.replaceState(null,'',location.pathname+location.hash);
  render();
  if(lineResult==='ok')toast('LINEでログインしました。');else if(lineResult==='linked')toast('LINEアカウントを連携しました。');else if(lineResult==='error')toast(lineErrors[params.get('reason')]||lineErrors.failed);
}catch(error){$('#app').innerHTML=empty('ストアを読み込めませんでした',error.message,'<button class="btn primary" id="retry">再読み込み</button>');$('#retry').onclick=()=>location.reload();}
